#!/usr/bin/env bash
# Canvas Remote MCP — one-shot installer for an Oracle Cloud Ubuntu VM.
#
# GENERATED by deploy/bundle.sh from setup.template.sh + the repo files.
# Edit the template, then re-run bundle.sh. Don't hand-edit oracle-setup.sh.
#
# Usage (on the VM, e.g. via Oracle Cloud Shell -> ssh):
#   sudo bash oracle-setup.sh
#
# Safe to re-run: it updates the code and restarts, keeping your .env,
# OAuth state and HTTPS cert.
set -euo pipefail

APP_DIR=/opt/canvas-mcp
[ "$(id -u)" -eq 0 ] || { echo "Run with sudo: sudo bash $0"; exit 1; }

say() { printf '\n\033[1;36m==> %s\033[0m\n' "$*"; }

# --- 1. swap (the 1 GB micro VM needs it to build the image) ----------------
if [ "$(awk '/MemTotal/{print $2}' /proc/meminfo)" -lt 3000000 ] && ! swapon --show | grep -q /swapfile; then
  say "Adding 2 GB swap (small VM)"
  fallocate -l 2G /swapfile && chmod 600 /swapfile && mkswap /swapfile >/dev/null && swapon /swapfile
  grep -q /swapfile /etc/fstab || echo '/swapfile none swap sw 0 0' >> /etc/fstab
fi

# --- 2. docker ---------------------------------------------------------------
if ! command -v docker >/dev/null || ! docker compose version >/dev/null 2>&1; then
  say "Installing Docker"
  curl -fsSL https://get.docker.com | sh
fi
systemctl enable --now docker >/dev/null

# --- 3. OS firewall -------------------------------------------------------------
# Oracle's Ubuntu images ship an iptables REJECT rule that blocks 80/443 even
# after you open them in the VCN security list. Punch holes above it.
say "Opening ports 80 and 443 in the VM firewall"
for p in 80 443; do
  iptables -C INPUT -p tcp --dport "$p" -j ACCEPT 2>/dev/null \
    || iptables -I INPUT 5 -p tcp -m state --state NEW --dport "$p" -j ACCEPT
done
if command -v netfilter-persistent >/dev/null; then netfilter-persistent save >/dev/null 2>&1 || true; fi

# --- 4. app files -------------------------------------------------------------------
say "Writing app to $APP_DIR"
mkdir -p "$APP_DIR"
cd "$APP_DIR"
#@@FILES@@

# --- 5. secrets (.env) — only asked the first time ----------------------------
if [ ! -f .env ]; then
  say "First-time setup: paste your secrets (input for secrets is hidden)"
  IP=$(curl -fsS https://api.ipify.org || true)
  DEFAULT_DOMAIN="${IP//./-}.sslip.io"
  read -rp  "Domain [$DEFAULT_DOMAIN]: " DOMAIN; DOMAIN=${DOMAIN:-$DEFAULT_DOMAIN}
  read -rsp "Canvas API token: " CANVAS_API_TOKEN; echo
  read -rp  "Canvas URL [https://yourschool.instructure.com]: " CANVAS_BASE_URL
  CANVAS_BASE_URL=${CANVAS_BASE_URL:-https://yourschool.instructure.com}
  read -rp  "GitHub OAuth client ID [Ov23linmhs7OYZsyGdG1]: " GITHUB_CLIENT_ID
  GITHUB_CLIENT_ID=${GITHUB_CLIENT_ID:-Ov23linmhs7OYZsyGdG1}
  read -rsp "GitHub OAuth client secret: " GITHUB_CLIENT_SECRET; echo
  read -rp  "Allowed GitHub users [Ashen00001]: " ALLOWED_GITHUB_USERS
  ALLOWED_GITHUB_USERS=${ALLOWED_GITHUB_USERS:-Ashen00001}
  umask 077
  cat > .env <<ENV
CANVAS_API_TOKEN=$CANVAS_API_TOKEN
CANVAS_BASE_URL=$CANVAS_BASE_URL
BASE_URL=https://$DOMAIN
DOMAIN=$DOMAIN
GITHUB_CLIENT_ID=$GITHUB_CLIENT_ID
GITHUB_CLIENT_SECRET=$GITHUB_CLIENT_SECRET
ALLOWED_GITHUB_USERS=$ALLOWED_GITHUB_USERS
ENV
  chmod 600 .env
fi
DOMAIN=$(grep '^DOMAIN=' .env | cut -d= -f2-)

# --- 6. start ----------------------------------------------------------------------
say "Building and starting (first build takes a few minutes)"
docker compose up -d --build

# --- 7. verify ---------------------------------------------------------------------
say "Waiting for HTTPS on https://$DOMAIN"
ok=""
for _ in $(seq 1 36); do
  if curl -fsS "https://$DOMAIN/.well-known/oauth-authorization-server" >/dev/null 2>&1; then ok=1; break; fi
  sleep 5
done
if [ -z "$ok" ]; then
  echo "HTTPS isn't up yet. Most likely the VCN security list doesn't allow 80/443."
  echo "Logs: cd $APP_DIR && docker compose logs --tail 50"
  exit 1
fi
code=$(curl -s -o /dev/null -w '%{http_code}' -X POST "https://$DOMAIN/" \
  -H 'Content-Type: application/json' -d '{"jsonrpc":"2.0","id":1,"method":"tools/list"}')
if [ "$code" != "401" ]; then
  echo "!! Unauthenticated request returned $code, expected 401. Server may be unprotected — stopping it."
  docker compose stop canvas; exit 1
fi

cat <<DONE

  Live and locked down:  https://$DOMAIN   (unauthenticated -> 401, good)

  Last two steps:
   1. GitHub OAuth app callback URL -> https://$DOMAIN/auth/callback
      https://github.com/settings/applications/3818524
   2. Claude -> Settings -> Connectors -> remove "canvas cloud", add a custom
      connector with URL
      https://$DOMAIN  and connect (GitHub login).

DONE
